package agent

import("bytes";"context";"encoding/json";"fmt";"net/http";"strings")
type OpenAICompatible struct{Endpoint,APIKey,Model string;Client *http.Client}
func(a OpenAICompatible)Decide(ctx context.Context,o Observation)(Decision,error){obs,_:=json.Marshal(o);schema:=`Return JSON only: {"orders":[],"statement":"..."}. Choose zero or more legal AGame orders. Never invent IDs.`;body:=map[string]any{"model":a.Model,"temperature":0.3,"messages":[]map[string]string{{"role":"system","content":schema},{"role":"user","content":string(obs)}}};b,_:=json.Marshal(body);url:=strings.TrimRight(a.Endpoint,"/")+"/v1/chat/completions";req,_:=http.NewRequestWithContext(ctx,"POST",url,bytes.NewReader(b));req.Header.Set("Content-Type","application/json");if a.APIKey!=""{req.Header.Set("Authorization","Bearer "+a.APIKey)};c:=a.Client;if c==nil{c=http.DefaultClient};resp,err:=c.Do(req);if err!=nil{return Decision{},err};defer resp.Body.Close();if resp.StatusCode/100!=2{return Decision{},fmt.Errorf("model HTTP %s",resp.Status)};var out struct{Choices []struct{Message struct{Content string `json:"content"`} `json:"message"`} `json:"choices"`};if err=json.NewDecoder(resp.Body).Decode(&out);err!=nil||len(out.Choices)==0{return Decision{},fmt.Errorf("invalid model response")};var d Decision;if err=json.Unmarshal([]byte(out.Choices[0].Message.Content),&d);err!=nil{return Decision{},err};return d,nil}
